import pandas as pd

def clean(df):
    df = df.copy()
    # Convert body_mass_g to numeric (remove commas in numbers like '3,150')
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].astype(str).str.replace(',', ''), errors='coerce')
    return df

def answer(df):
    df = clean(df)
    return df.groupby('species')['body_mass_g'].sum().to_dict()
